window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-959ebb668c3a39e2"]={"versions": [{"id": "FIG-959ebb668c3a39e2", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des logischen Programmablaufs innerhalb der Funktion <code>E2E_P04mForward()</code> (Schritt „Write Counter“). Das Diagramm gehört zum AUTOSAR-Standard für das End-to-End-Kommunikationsschutzprofil 4m (E2E Profile 4m) innerhalb der AUTOSAR-Spezifikation für E2E-Protokolle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm referenziert folgende Datenstrukturen, Variablen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Funktion: <code>E2E_P04mForward()</code>\n</li><li>Eingangs- und Zustandsvariablen:\n<ul class=\"fig-list\"><li><code>ForwardStatus</code> (Aufzählungswert mit Zuständen <code>E2E_P_REPEATED</code>, <code>E2E_P_WRONGSEQUENCE</code>)\n</li><li><code>State-&gt;Counter</code>: 16-Bit-Zähler (<code>uint16</code>), Überlauf/Wrap-around von <code>0xFFFF</code> nach <code>0</code>\n</li><li><code>Config-&gt;MaxDeltaCounter</code>: Konfigurationsparameter für die maximale Zählerdifferenz\n</li><li><code>Data[]</code>: Byte-Array des Datenpuffers\n</li><li><code>Offset</code>: Offset-Index innerhalb des Puffers <code>Data</code>\n</li></ul>\n</li><li>Aktionen und Kontrollknoten:\n<ul class=\"fig-list\"><li>Startknoten (Initial Node) und Endknoten (Activity Final Node)\n</li><li>Drei Verzweigungsknoten (Decision Nodes) und zwei Zusammenführungsknoten (Merge Nodes)\n</li><li>Kommentar-Notiz bezüglich des Datentyps <code>uint16</code> und Überlaufverhaltens von <code>State-&gt;Counter</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss verläuft sequentiell vom Startknoten durch eine mehrstufige Fallunterscheidung bezüglich des Status <code>ForwardStatus</code>:</p>\n<ol class=\"fig-list\"><li>Prüfung <code>if ForwardStatus == E2E_P_REPEATED</code>:\n<ul class=\"fig-list\"><li>Zweig <code>[TRUE]</code>: Dekrementierung des Zählers (<code>State-&gt;Counter--</code>).\n</li><li>Zweig <code>[FALSE]</code>: Weiterleitung zur nächsten Verzweigung.\n</li></ul>\n</li><li>Prüfung <code>if ForwardStatus == E2E_P_WRONGSEQUENCE</code>:\n<ul class=\"fig-list\"><li>Zweig <code>[TRUE]</code>: Anpassung des Zählers über <code>State-&gt;Counter = State-&gt;Counter + Config-&gt;MaxDeltaCounter</code>.\n</li><li>Zweig <code>else</code>: Keine Zähleranpassung (Bypass direkt zum Merge Node).\n</li></ul>\n</li><li>Zusammenführung aller drei Pfade über Zusammenführungsknoten.\n</li><li>Ausführung der Aktion: <code>Copy 2-byte State-&gt;Counter on bytes Data[Offset+2...Offset+3] in Big Endian order</code>.\n</li><li>Erreichen des Endknotens.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation für Implementierer des AUTOSAR E2E Profile 4m Forward-Mechanismus:</p>\n<ul class=\"fig-list\"><li>Die Manipulation von <code>State-&gt;Counter</code> muss strikt abhängig vom ermittelten <code>ForwardStatus</code> erfolgen, bevor der Zählerwert in den Datenstrom serialisiert wird.\n</li><li>Der Zählerwert ist als 16-Bit vorzeichenlose Ganzzahl (<code>uint16</code>) mit modulo-arithmetischem Verhalten (<code>0xFFFF</code> -&gt; <code>0</code>) zu führen.\n</li><li>Das Schreiben in das Datenarray <code>Data</code> erfolgt zwingend in Big-Endian-Byte-Reihenfolge (Most Significant Byte an <code>Offset+2</code>, Least Significant Byte an <code>Offset+3</code>).\n</li></ul>"}, {"id": "FIG-8dab0443df1ae60a", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des logischen Programmablaufs innerhalb der Funktion <code>E2E_P04mForward()</code> (Schritt „Write Counter“). Das Diagramm gehört zum AUTOSAR-Standard für das End-to-End-Kommunikationsschutzprofil 4m (E2E Profile 4m) innerhalb der AUTOSAR-Spezifikation für E2E-Protokolle.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm referenziert folgende Datenstrukturen, Variablen und Schnittstellen:</p>\n<ul class=\"fig-list\"><li>Funktion: <code>E2E_P04mForward()</code>\n</li><li>Eingangs- und Zustandsvariablen:\n<ul class=\"fig-list\"><li><code>ForwardStatus</code> (Aufzählungswert mit Zuständen <code>E2E_P_REPEATED</code>, <code>E2E_P_WRONGSEQUENCE</code>)\n</li><li><code>State-&gt;Counter</code>: 16-Bit-Zähler (<code>uint16</code>), Überlauf/Wrap-around von <code>0xFFFF</code> nach <code>0</code>\n</li><li><code>Config-&gt;MaxDeltaCounter</code>: Konfigurationsparameter für die maximale Zählerdifferenz\n</li><li><code>Data[]</code>: Byte-Array des Datenpuffers\n</li><li><code>Offset</code>: Offset-Index innerhalb des Puffers <code>Data</code>\n</li></ul>\n</li><li>Aktionen und Kontrollknoten:\n<ul class=\"fig-list\"><li>Startknoten (Initial Node) und Endknoten (Activity Final Node)\n</li><li>Drei Verzweigungsknoten (Decision Nodes) und zwei Zusammenführungsknoten (Merge Nodes)\n</li><li>Kommentar-Notiz bezüglich des Datentyps <code>uint16</code> und Überlaufverhaltens von <code>State-&gt;Counter</code>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Kontrollfluss verläuft sequentiell vom Startknoten durch eine mehrstufige Fallunterscheidung bezüglich des Status <code>ForwardStatus</code>:</p>\n<ol class=\"fig-list\"><li>Prüfung <code>if ForwardStatus == E2E_P_REPEATED</code>:\n<ul class=\"fig-list\"><li>Zweig <code>[TRUE]</code>: Dekrementierung des Zählers (<code>State-&gt;Counter--</code>).\n</li><li>Zweig <code>[FALSE]</code>: Weiterleitung zur nächsten Verzweigung.\n</li></ul>\n</li><li>Prüfung <code>if ForwardStatus == E2E_P_WRONGSEQUENCE</code>:\n<ul class=\"fig-list\"><li>Zweig <code>[TRUE]</code>: Anpassung des Zählers über <code>State-&gt;Counter = State-&gt;Counter + Config-&gt;MaxDeltaCounter</code>.\n</li><li>Zweig <code>else</code>: Keine Zähleranpassung (Bypass direkt zum Merge Node).\n</li></ul>\n</li><li>Zusammenführung aller drei Pfade über Zusammenführungsknoten.\n</li><li>Ausführung der Aktion: <code>Copy 2-byte State-&gt;Counter on bytes Data[Offset+2...Offset+3] in Big Endian order</code>.\n</li><li>Erreichen des Endknotens.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ bindende Spezifikation für Implementierer des AUTOSAR E2E Profile 4m Forward-Mechanismus:</p>\n<ul class=\"fig-list\"><li>Die Manipulation von <code>State-&gt;Counter</code> muss strikt abhängig vom ermittelten <code>ForwardStatus</code> erfolgen, bevor der Zählerwert in den Datenstrom serialisiert wird.\n</li><li>Der Zählerwert ist als 16-Bit vorzeichenlose Ganzzahl (<code>uint16</code>) mit modulo-arithmetischem Verhalten (<code>0xFFFF</code> -&gt; <code>0</code>) zu führen.\n</li><li>Das Schreiben in das Datenarray <code>Data</code> erfolgt zwingend in Big-Endian-Byte-Reihenfolge (Most Significant Byte an <code>Offset+2</code>, Least Significant Byte an <code>Offset+3</code>).\n</li></ul>"}], "trans": [{"from": "FIG-959ebb668c3a39e2", "to": "FIG-8dab0443df1ae60a", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
